static void ck(VkResult r){if(r!=VK_SUCCESS)throw std::runtime_error("Vulkan error "+std::to_string(r));}
struct Buffer {VkBuffer b{};VkDeviceMemory mem{};void* map{};VkDeviceSize size{};};
struct Push {uint32_t n,d,k,stage,chunks,step;float lr,l2;};
struct Trainer {
 VkInstance instance{};VkPhysicalDevice physical{};VkDevice device{};VkQueue queue{};VkCommandPool pool{};VkCommandBuffer cmd{};VkFence fence{};
 VkDescriptorPool dp{};VkDescriptorSetLayout dsl{};VkDescriptorSet ds{};VkPipelineLayout pl{};VkPipeline pipeline{};VkShaderModule shader{};
 VkPhysicalDeviceMemoryProperties memories{};std::vector<Buffer> b;uint32_t d,k,capacity,step=0;std::string name;
 Buffer alloc(VkDeviceSize bytes){Buffer a;a.size=bytes;VkBufferCreateInfo ci{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};ci.size=bytes;ci.usage=VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;ci.sharingMode=VK_SHARING_MODE_EXCLUSIVE;ck(vkCreateBuffer(device,&ci,nullptr,&a.b));VkMemoryRequirements req;vkGetBufferMemoryRequirements(device,a.b,&req);uint32_t idx=UINT32_MAX;auto flags=VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;for(uint32_t i=0;i<memories.memoryTypeCount;i++)if((req.memoryTypeBits&(1u<<i))&&(memories.memoryTypes[i].propertyFlags&flags)==flags){idx=i;break;}if(idx==UINT32_MAX)throw std::runtime_error("No coherent host-visible memory");VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=req.size;ai.memoryTypeIndex=idx;ck(vkAllocateMemory(device,&ai,nullptr,&a.mem));ck(vkBindBufferMemory(device,a.b,a.mem,0));ck(vkMapMemory(device,a.mem,0,bytes,0,&a.map));memset(a.map,0,bytes);return a;}
 Trainer(const char* path,uint32_t width,uint32_t choices,uint32_t maxbatch):d(width),k(choices),capacity(maxbatch){
  VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};app.pApplicationName="D-Trade verified decision-head fine-tuning";app.apiVersion=VK_API_VERSION_1_1;VkInstanceCreateInfo ii{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};ii.pApplicationInfo=&app;ck(vkCreateInstance(&ii,nullptr,&instance));uint32_t n;ck(vkEnumeratePhysicalDevices(instance,&n,nullptr));std::vector<VkPhysicalDevice> devs(n);ck(vkEnumeratePhysicalDevices(instance,&n,devs.data()));for(auto p:devs){VkPhysicalDeviceProperties props;vkGetPhysicalDeviceProperties(p,&props);if(props.deviceType==VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU){physical=p;name=props.deviceName;break;}}if(!physical)throw std::runtime_error("No discrete Vulkan GPU");vkGetPhysicalDeviceMemoryProperties(physical,&memories);vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,nullptr);std::vector<VkQueueFamilyProperties> fs(n);vkGetPhysicalDeviceQueueFamilyProperties(physical,&n,fs.data());uint32_t family=UINT32_MAX;for(uint32_t i=0;i<n;i++)if(fs[i].queueFlags&VK_QUEUE_COMPUTE_BIT){family=i;break;}if(family==UINT32_MAX)throw std::runtime_error("No compute queue");float priority=1;VkDeviceQueueCreateInfo qi{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};qi.queueFamilyIndex=family;qi.queueCount=1;qi.pQueuePriorities=&priority;VkDeviceCreateInfo di{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};di.queueCreateInfoCount=1;di.pQueueCreateInfos=&qi;ck(vkCreateDevice(physical,&di,nullptr,&device));vkGetDeviceQueue(device,family,0,&queue);
  VkCommandPoolCreateInfo pi{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};pi.queueFamilyIndex=family;pi.flags=VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;ck(vkCreateCommandPool(device,&pi,nullptr,&pool));VkCommandBufferAllocateInfo ca{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};ca.commandPool=pool;ca.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;ca.commandBufferCount=1;ck(vkAllocateCommandBuffers(device,&ca,&cmd));VkFenceCreateInfo fi{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};ck(vkCreateFence(device,&fi,nullptr,&fence));
  VkDescriptorSetLayoutBinding bindings[7]{};for(uint32_t i=0;i<7;i++){bindings[i].binding=i;bindings[i].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;bindings[i].descriptorCount=1;bindings[i].stageFlags=VK_SHADER_STAGE_COMPUTE_BIT;}VkDescriptorSetLayoutCreateInfo li{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};li.bindingCount=7;li.pBindings=bindings;ck(vkCreateDescriptorSetLayout(device,&li,nullptr,&dsl));VkDescriptorPoolSize ps{VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,7};VkDescriptorPoolCreateInfo dpi{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};dpi.maxSets=1;dpi.poolSizeCount=1;dpi.pPoolSizes=&ps;ck(vkCreateDescriptorPool(device,&dpi,nullptr,&dp));VkDescriptorSetAllocateInfo da{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};da.descriptorPool=dp;da.descriptorSetCount=1;da.pSetLayouts=&dsl;ck(vkAllocateDescriptorSets(device,&da,&ds));
  VkPushConstantRange push{VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof(Push)};VkPipelineLayoutCreateInfo pli{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};pli.setLayoutCount=1;pli.pSetLayouts=&dsl;pli.pushConstantRangeCount=1;pli.pPushConstantRanges=&push;ck(vkCreatePipelineLayout(device,&pli,nullptr,&pl));std::ifstream file(path,std::ios::binary|std::ios::ate);if(!file)throw std::runtime_error("Cannot open shader");size_t bytes=file.tellg();file.seekg(0);std::vector<uint32_t> code((bytes+3)/4);file.read((char*)code.data(),bytes);VkShaderModuleCreateInfo sm{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};sm.codeSize=bytes;sm.pCode=code.data();ck(vkCreateShaderModule(device,&sm,nullptr,&shader));VkComputePipelineCreateInfo cp{VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO};cp.stage.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;cp.stage.stage=VK_SHADER_STAGE_COMPUTE_BIT;cp.stage.module=shader;cp.stage.pName="main";cp.layout=pl;ck(vkCreateComputePipelines(device,VK_NULL_HANDLE,1,&cp,nullptr,&pipeline));
  std::vector<size_t> sizes={size_t(capacity)*k*d*4,d*4,size_t(capacity)*k*4,size_t(capacity)*k*4,size_t(d)*((capacity+127)/128)*4,capacity*4,d*2*4};for(auto size:sizes)b.push_back(alloc(size));VkDescriptorBufferInfo infos[7];VkWriteDescriptorSet writes[7]{};for(uint32_t i=0;i<7;i++){infos[i]={b[i].b,0,b[i].size};writes[i].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;writes[i].dstSet=ds;writes[i].dstBinding=i;writes[i].descriptorCount=1;writes[i].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;writes[i].pBufferInfo=&infos[i];}vkUpdateDescriptorSets(device,7,writes,0,nullptr);fprintf(stderr,"Vulkan training device: %s; trainable scorer weights=%u\n",name.c_str(),d);
 }
 void barrier(VkPipelineStageFlags src,VkPipelineStageFlags dst,VkAccessFlags from,VkAccessFlags to){VkMemoryBarrier mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER};mb.srcAccessMask=from;mb.dstAccessMask=to;vkCmdPipelineBarrier(cmd,src,dst,0,1,&mb,0,nullptr,0,nullptr);}
 void run(const float* x,const uint32_t* y,float* logits,float* gradient,uint32_t n,float lr,float l2,bool update){if(!n||n>capacity)throw std::runtime_error("Invalid batch size");memcpy(b[0].map,x,size_t(n)*k*d*4);if(y)memcpy(b[5].map,y,n*4);ck(vkResetCommandBuffer(cmd,0));VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};bi.flags=VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;ck(vkBeginCommandBuffer(cmd,&bi));barrier(VK_PIPELINE_STAGE_HOST_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_ACCESS_HOST_WRITE_BIT,VK_ACCESS_SHADER_READ_BIT|VK_ACCESS_SHADER_WRITE_BIT);vkCmdBindPipeline(cmd,VK_PIPELINE_BIND_POINT_COMPUTE,pipeline);vkCmdBindDescriptorSets(cmd,VK_PIPELINE_BIND_POINT_COMPUTE,pl,0,1,&ds,0,nullptr);Push p{n,d,k,0,(n+127)/128,step+(update?1u:0u),lr,l2};uint32_t sizes[4]={n*k,n,d*p.chunks,d};for(uint32_t s=0;s<(y?(update?4u:3u):1u);s++){p.stage=s;vkCmdPushConstants(cmd,pl,VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof(Push),&p);vkCmdDispatch(cmd,(sizes[s]+63)/64,1,1);barrier(VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_ACCESS_SHADER_WRITE_BIT,VK_ACCESS_SHADER_READ_BIT|VK_ACCESS_SHADER_WRITE_BIT);}barrier(VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_HOST_BIT,VK_ACCESS_SHADER_WRITE_BIT,VK_ACCESS_HOST_READ_BIT);ck(vkEndCommandBuffer(cmd));ck(vkResetFences(device,1,&fence));VkSubmitInfo si{VK_STRUCTURE_TYPE_SUBMIT_INFO};si.commandBufferCount=1;si.pCommandBuffers=&cmd;ck(vkQueueSubmit(queue,1,&si,fence));ck(vkWaitForFences(device,1,&fence,VK_TRUE,60000000000ull));if(logits)memcpy(logits,b[2].map,size_t(n)*k*4);if(gradient){auto g=(float*)b[4].map;for(uint32_t j=0;j<d;j++){gradient[j]=0;for(uint32_t ch=0;ch<p.chunks;ch++)gradient[j]+=g[ch*d+j];}}if(update)step++;}
 ~Trainer(){if(!device)return;vkDeviceWaitIdle(device);for(auto& a:b){vkUnmapMemory(device,a.mem);vkDestroyBuffer(device,a.b,nullptr);vkFreeMemory(device,a.mem,nullptr);}vkDestroyPipeline(device,pipeline,nullptr);vkDestroyShaderModule(device,shader,nullptr);vkDestroyPipelineLayout(device,pl,nullptr);vkDestroyDescriptorPool(device,dp,nullptr);vkDestroyDescriptorSetLayout(device,dsl,nullptr);vkDestroyFence(device,fence,nullptr);vkDestroyCommandPool(device,pool,nullptr);vkDestroyDevice(device,nullptr);vkDestroyInstance(instance,nullptr);}
};
extern "C" {
void* dt_create(const char* path,uint32_t d,uint32_t k,uint32_t batch){try{return new Trainer(path,d,k,batch);}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return nullptr;}}
int dt_set(void* h,const float* w){auto t=(Trainer*)h;memcpy(t->b[1].map,w,t->d*4);memset(t->b[6].map,0,t->d*2*4);t->step=0;return 0;}
int dt_get(void* h,float* w){auto t=(Trainer*)h;memcpy(w,t->b[1].map,t->d*4);return 0;}
int dt_run(void* h,const float* x,const uint32_t* y,float* logits,float* g,uint32_t n,float lr,float l2,int update){try{((Trainer*)h)->run(x,y,logits,g,n,lr,l2,update);return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return -1;}}
const char* dt_name(void* h){return ((Trainer*)h)->name.c_str();}
void dt_destroy(void* h){delete (Trainer*)h;}
}
